"import os
import json
import ftplib
import sys

def load_config(config_path="meow.config.json"):
    if not os.path.exists(config_path):
        print(f"Error: {config_path} not found.")
        sys.exit(1)
    with open(config_path, "r") as f:
        return json.load(f)

def make_dirs_recursive(ftp, remote_dir):
    parts = [p for p in remote_dir.split('/') if p]
    path = ''
    for part in parts:
        path += '/' + part
        try:
            ftp.cwd(path)
        except ftplib.error_perm:
            try:
                ftp.mkd(path)
            except ftplib.error_perm:
                pass

def upload_directory(ftp, local_dir, remote_dir):
    make_dirs_recursive(ftp, remote_dir)
    ftp.cwd(remote_dir)

    for item in os.listdir(local_dir):
        local_path = os.path.join(local_dir, item)
        if os.path.isfile(local_path):
            with open(local_path, "rb") as f:
                print(f"Uploading {item} to {remote_dir}...")
                ftp.storbinary(f"STOR {item}", f)
        elif os.path.isdir(local_path):
            sub_remote = f"{remote_dir}/{item}"
            upload_directory(ftp, local_path, sub_remote)
            ftp.cwd(remote_dir)

def main():
    config = load_config()
    host = config.get("host")
    user = config.get("user")
    password=[REDACTED]password")

    # NOTE: Credentials kept local. Do not sync to GitHub.
    ftp = ftplib.FTP(host)
    ftp.login(user, password)

    for target in config.get("targets", []):
        local_dir = target["local_dir"]
        remote_dirs = target["remote_dirs"]
        for rdir in remote_dirs:
            print(f"\n--- Syncing {local_dir} to {rdir} ---")
            upload_directory(ftp, local_dir, rdir)

    ftp.quit()
